import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecureFileWrite {
    public static void main(String[] args) {
        String userInput = "safe_filename.txt";

        // Define the base directory securely
        Path baseDir = Paths.get("/var/log/app");

        // Resolve the user input against the base directory
        // This prevents path traversal by normalizing the path
        Path resolvedPath = baseDir.resolve(userInput).normalize();

        // Security Check: Ensure the resolved path is still within the base directory
        if (!resolvedPath.startsWith(baseDir)) {
            throw new SecurityException("Invalid file path: Access denied");
        }

        try {
            // Safe to write now that we've validated the path
            FileWriter writer = new FileWriter(resolvedPath.toFile());
            writer.write("Safe content");
            writer.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
